import { useRef, useState } from 'react';
import { ARTS } from '../data/articles';
import type { Article } from '../data/types';
import { goTo, refreshSoon } from '../lib/motion';
import { useSectionMotion } from '../hooks/useSectionMotion';
import { Arrow, Search, Words } from '../lib/ui';

const CHIPS = [
  'Who owns the copyright to output generated by AI under UK vs. Indian law?',
  'When should a startup file an international trademark under the Madrid System?',
  'Do I need IP assignments from freelance developers in India?'
];

interface Answer { text: string; sources: Article[] }

function search(q: string): Answer {
  const t = q.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  const top = ARTS
    .map(a => ({ a, s: t.filter(w => a.kw.includes(w)).length * 2 + t.filter(w => a.title.toLowerCase().includes(w)).length }))
    .sort((x, y) => y.s - x.s).filter(x => x.s > 1).slice(0, 2).map(x => x.a);
  return top.length
    ? { text: top.map(a => a.summary).join(' '), sources: top }
    : { text: 'Bipasha has not yet published on this question. Book a consultation for a direct answer.', sources: [] };
}

export default function Insights() {
  const root = useRef<HTMLElement>(null);
  const [q, setQ] = useState('');
  const [loading, setLoading] = useState(false);
  const [answer, setAnswer] = useState<Answer | null>(null);
  useSectionMotion(root);

  const ask = (raw: string) => {
    const text = raw.trim();
    if (!text) return;
    setQ(text); setAnswer(null); setLoading(true);
    window.setTimeout(() => { setAnswer(search(text)); setLoading(false); refreshSoon(); }, 600);
  };
  const openArticle = (a: Article) => { setQ(a.title); setAnswer({ text: a.summary, sources: [a] }); refreshSoon(); goTo('#kbQ'); };

  return (
    <section className="sec light" id="insights" ref={root}>
      <div className="tool-head" style={{ marginBottom: 36 }}>
        <div data-rv>
          <div className="eyebrow"><span>Tool 03 · Knowledge base</span></div>
          <h2 className="display h2" style={{ maxWidth: 1000 }}><Words text="Ask a legal question." /> <Words text="Hear it from Bipasha’s writing." em /></h2>
        </div>
      </div>
      <div className="kb-bar" data-rv>
        <input id="kbQ" value={q} placeholder="Ask in plain language — e.g. who owns AI-generated output?" aria-label="Your question" autoComplete="off"
          onChange={e => setQ(e.target.value)} onKeyDown={e => e.key === 'Enter' && ask(q)} />
        <button className="btn solid" disabled={!q.trim() || loading} onClick={() => ask(q)}>Ask <Search /></button>
      </div>
      <div className="chips" data-rv>{CHIPS.map(c => <button key={c} className="chip" onClick={() => ask(c)}>{c}</button>)}</div>

      <div aria-live="polite">
        {loading && <div style={{ padding: '28px 0', display: 'flex', gap: 12, alignItems: 'center', fontWeight: 600 }}><span className="live" style={{ display: 'inline-flex' }}><i /></span>Searching published writing…</div>}
        {answer && (
          <div className="kb-ans">
            <div>
              <h5>Executive answer</h5>
              <p className="a">{answer.text}</p>
              <p style={{ fontSize: 12, opacity: 0.7 }}>Drawn only from Bipasha’s published writing. For information only — not legal advice.</p>
            </div>
            <div>
              <h5>Sources</h5>
              {answer.sources.map(a => <a key={a.id} className="src" href="#articles"><b>0{a.id}</b><span>{a.title}</span><span>→</span></a>)}
              {!answer.sources.length && <a className="btn solid" href="#consult">Ask Bipasha directly <Arrow /></a>}
            </div>
          </div>
        )}
      </div>

      <div className="articles" id="articles">
        {ARTS.map(a => (
          <button key={a.id} className="art" onClick={() => openArticle(a)}>
            <div className="m"><span>{a.tag}</span><span>{a.date}</span></div>
            <h3>{a.title}</h3>
            <span className="go">Summarise →</span>
          </button>
        ))}
      </div>
    </section>
  );
}
